/* 090d:003e: strength of the outcome side's active groups. */
uint16_t opeu_end_unit_strength(uint8_t ds[65536], HostEvent event) {
  uint16_t value;
  uint8_t  g;
  UNIT_PTR elem;
  uint8_t  slot;
  (void)event;
  value = 0;
  for (g = 0; g < 4; g++) {
    elem = UNIT_FIRST(SIDE * 4 + g);
    if (GROUP_FLAGS(SIDE * 4 + g) & 4)
      for (slot = 0; slot < 8; slot++, UNIT_NEXT(elem))
        if (UNIT_FLAGS(elem) & 4)
          value += UNIT_VALUE(elem) / 100;
  }
  return value;
}

/* 090d:00b4: points of the objectives the outcome side holds. */
uint16_t opeu_end_objective_points(uint8_t ds[65536], HostEvent event) {
  uint16_t value;
  OBJ_PTR  obj;
  uint8_t  slot;
  (void)event;
  value = 0;
  obj   = OBJ_FIRST;
  for (slot = 0; slot < 21; OBJ_NEXT(obj), slot++)
    if (OBJ_USED(obj) && OBJECTIVE_SIDE(obj) == SIDE)
      value += OBJ_POINTS(obj);
  return value;
}

