/* 090d:0126: outcome screen, epilogue and the final wait; never returns. */
void opeu_scenario_end(uint8_t ds[65536], HostEvent event, uint16_t sp) {
  BUFFER(pattern, 0x1fc);
  BUFFER(caption, 0x102);
  int16_t picture, prevailed, handle, rank;
  (void)event;
  RANK_START;
  if ((prevailed = SIDE_STATUS(SIDE) == 1)) {
    TURN_CONTEXT(12);
    picture = SIDE ? 0x93 : 0x1b;
    if (REASON == 0) {
      COPY_FAR(pattern, VICTORY_TEXT(0));
      FORMAT(caption, pattern, MONTH, DAY, SIDE_RECORD(OPPOSITE(SIDE), 1));
    } else {
      SET_SCORE(CALL_STRENGTH());
      ADD_SCORE(CALL_POINTS());
      SET_SCORE(MIN16(SCORE, 1000));
      if (REASON == 1)
        ADD_SCORE(100);
      if (SCORE >= 350)
        rank = 1;
      if (SCORE >= 200 && SCORE < 350)
        rank = 2;
      if (SCORE < 200)
        rank = 3;
      COPY_FAR(pattern, VICTORY_TEXT(rank));
      FORMAT(caption, pattern, MONTH, DAY, SIDE_RECORD(SIDE, 1));
    }
  } else {
    TURN_CONTEXT(11);
    picture = SIDE ? 0xd9 : 0x50;
    COPY_FAR(pattern, DEFEAT_TEXT(REASON));
    FORMAT(caption, pattern, MONTH, DAY, SIDE_RECORD(OPPOSITE(SIDE), 1));
  }
  VGA_CLEAR();
  MAP_PALETTE();
  handle = OPEN(DATA_NAME);
  PICTURE(80, 64, handle, picture);
  CLOSE(handle);
  POSITION(9, 336);
  PRINT1(TEXT_FORMAT, caption);
  FINISH_INIT(1);
  DELAY(0x93);
  if (SIDE_CONTROL(SIDE) == 1) {
    TURN_CONTEXT(19);
    FINISH_INIT(0);
    handle = OPEN(PICTURE_NAME);
    VGA_CLEAR();
    CALL_DARK();
    PICTURE_MASKED(0, 55, handle, 0);
    POSITION(12, 300);
    PRINT(LOOKUP(8));
    PRINT(LOOKUP(9));
    PRINT(LOOKUP(10));
    PRINT(LOOKUP(11));
    DELAY(0x68);
    DELAY(0xb4);
    VGA_CLEAR();
    CALL_DARK();
    PICTURE_AT(0, 85, handle, 0x3d20L);
    POSITION(12, 350);
    PRINT(LOOKUP(0x34));
    PRINT(LOOKUP(0x35));
    PRINT(LOOKUP(0x36));
    DELAY(0x68);
    DELAY(0xb4);
    VGA_CLEAR();
    CALL_DARK();
    PICTURE_AT(160, 35, handle, 0xb4b1L);
    POSITION(12, 300);
    PRINT(LOOKUP(0x4c));
    PRINT(LOOKUP(0x4d));
    PRINT(LOOKUP(0x4e));
    PRINT(LOOKUP(0x4f));
    DELAY(0x68);
    DELAY(0xb4);
    VGA_CLEAR();
    CALL_DARK();
    PICTURE_AT(160, 35, handle, 0xd03bL);
    POSITION(12, 280);
    PRINT(LOOKUP(4));
    PRINT(LOOKUP(7));
    PRINT(LOOKUP(0x37));
    PRINT(LOOKUP(0x63));
    PRINT1(SALUTE, SIDE_RECORD(SIDE, 1));
    DELAY(0x68);
    DELAY(0xb4);
    VGA_CLEAR();
    CALL_SHOW();
    PICTURE_AT(0, 0, handle, 0x10c78L);
    DELAY(0x1e);
    PICTURE_AT(128, 112, handle, 0x13829L);
    CLOSE(handle);
  }
  FLUSH();
  DELAY(0x1e);
  for (;;) {
    if (!MUSIC())
      QUIT();
    if (INPUT_MODE ? INPUT_A() : INPUT_B())
      QUIT();
  }
}

/* 090d:0536: report a failed segment release (the name is not shown). */
void opeu_free_error(uint8_t ds[65536], HostEvent event, uint16_t name) {
  (void)name;
  VGA_CLEAR();
  POSITION(0, 0);
}

/* 090d:0544: release the DOS memory segments (EMS-mapped ones stay). */
void opeu_free_segments(uint8_t ds[65536], HostEvent event) {
  if (!FREE(S_BMAP))
    CALL_FREE_ERROR(N_BMAP);
  if (!TILE_MAPPED && !FREE(S_MMAP))
    CALL_FREE_ERROR(N_MMAP);
  if (!FREE(S_HDISP))
    CALL_FREE_ERROR(N_HDISP);
  if (!FREE(S_HUNIT))
    CALL_FREE_ERROR(N_HUNIT);
  if (!FREE(S_GRP))
    CALL_FREE_ERROR(N_GRP);
  if (!FREE(S_MS_WIN))
    CALL_FREE_ERROR(N_MS_WIN);
  if (!NUMDLG_IMAGE_MAPPED && !FREE(S_MS))
    CALL_FREE_ERROR(N_MS);
  if (!SPRITE_MAPPED && !FREE(S_HFONT))
    CALL_FREE_ERROR(N_HFONT);
  if (!FREE(S_V))
    CALL_FREE_ERROR(N_V);
  if (!FREE(S_KAO))
    CALL_FREE_ERROR(N_KAO);
  if (!FREE(S_ARMS))
    CALL_FREE_ERROR(N_ARMS);
  if (!FRAME_MAPPED && !FREE(S_MDISP))
    CALL_FREE_ERROR(N_MDISP);
}

/* 090d:0682: close the portrait, face and message-picture files. */
void opeu_close_data_files(uint8_t ds[65536], HostEvent event) {
  (void)event;
  CLOSE(PORTRAIT_HANDLE);
  CLOSE(FACE_HANDLE);
  CLOSE(PICTURE_HANDLE);
}

/* 090d:06a8: APP's end of the game. */
void opeu_app_finish(uint8_t ds[65536], HostEvent event, uint16_t sp) {
  CALL_SCENARIO_END();
}

